import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

type DocumentOut = { id: string; vendor_id: string; kind: string; status: string };
type ExtractionOut = { id: string; document_id: string; kind: string; status: string };
type VendorOut = { id: string; status: string };
type AuditTrail = { items: Array<{ action: string }> };

function uniqueSuffix(): string {
  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
}

async function createVendor(member: APIRequestContext, suffix: string): Promise<VendorOut> {
  const response = await member.post("/api/vendors", {
    data: {
      name: `LIF-06 Vendor ${suffix}`,
      category: "services",
      contact_email: `ap-${suffix}@example.com`,
    },
  });
  return expectStatus<VendorOut>(response, 201);
}

async function uploadDocument(
  member: APIRequestContext,
  vendorId: string,
  kind: "w9" | "insurance_certificate" | "contract",
  label: string,
): Promise<DocumentOut> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${label}.pdf`,
        mimeType: "application/pdf",
        buffer: Buffer.from(`%PDF-1.4 ${label}`),
      },
    },
  });
  return expectStatus<DocumentOut>(response, 201);
}

async function waitForExtraction(
  reviewer: APIRequestContext,
  documentId: string,
): Promise<ExtractionOut> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const documentResponse = await reviewer.get(`/api/documents/${documentId}`);
    const document = await expectStatus<DocumentOut>(documentResponse, 200);
    if (document.status === "failed") {
      throw new Error(`document ${documentId} failed extraction`);
    }
    if (document.status === "extracted") {
      const extractionResponse = await reviewer.get(`/api/documents/${documentId}/extraction`);
      return expectStatus<ExtractionOut>(extractionResponse, 200);
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`document ${documentId} was not extracted in time`);
}

async function decide(
  reviewer: APIRequestContext,
  extractionId: string,
  decision: "approve" | "reject",
  note?: string,
) {
  const response = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
    data: note === undefined ? { decision } : { decision, note },
  });
  return expectStatus<ExtractionOut>(response, 200);
}

test(
  "approving the replacement approves a vendor whose other documents were already approved",
  { tag: "@LIF-06" },
  async ({ apiAs }) => {
    // Arrange: a vendor with an approved insurance certificate and a rejected first w9.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const suffix = uniqueSuffix();

    const vendor = await createVendor(member, suffix);

    const insurance = await uploadDocument(member, vendor.id, "insurance_certificate", `insurance-${suffix}`);
    const originalW9 = await uploadDocument(member, vendor.id, "w9", `w9-original-${suffix}`);

    await expectStatus<VendorOut>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

    const insuranceExtraction = await waitForExtraction(reviewer, insurance.id);
    expect(insuranceExtraction.status).toBe("pending_review");
    const insuranceDecision = await decide(reviewer, insuranceExtraction.id, "approve");
    expect(insuranceDecision.status).toBe("approved");

    const originalExtraction = await waitForExtraction(reviewer, originalW9.id);
    expect(originalExtraction.status).toBe("pending_review");
    const rejection = await decide(reviewer, originalExtraction.id, "reject", "Signature missing");
    expect(rejection.status).toBe("rejected");

    // Arrange: upload a replacement w9 and resubmit, so it is the only pending extraction.
    const replacementW9 = await uploadDocument(member, vendor.id, "w9", `w9-replacement-${suffix}`);
    await expectStatus<VendorOut>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

    const replacementExtraction = await waitForExtraction(reviewer, replacementW9.id);
    expect(replacementExtraction.kind).toBe("w9");
    expect(replacementExtraction.status).toBe("pending_review");

    // Act
    const approval = await decide(reviewer, replacementExtraction.id, "approve");

    // Assert: the replacement extraction is approved and the vendor is approved.
    expect(approval.status).toBe("approved");

    const vendorResponse = await reviewer.get(`/api/vendors/${vendor.id}`);
    const approvedVendor = await expectStatus<VendorOut>(vendorResponse, 200);
    expect(approvedVendor.status).toBe("approved");

    const auditResponse = await reviewer.get(`/api/vendors/${vendor.id}/audit`);
    const audit = await expectStatus<AuditTrail>(auditResponse, 200);
    expect(audit.items.map((event) => event.action)).toContain("vendor.approved");
  },
);
